describe('Comment on a Record', () => {
  const baseUrl = Cypress.env('BASE_URL') || 'http://localhost:3000';
  const testUser = {
    email: 'testuser@example.com',
    password: 'TestPassword123!'
  };

  beforeEach(() => {
    cy.visit(`${baseUrl}/login`);
    cy.get('input[name="email"]').type(testUser.email);
    cy.get('input[name="password"]').type(testUser.password);
    cy.get('button[type="submit"]').click();
    cy.url().should('include', '/dashboard');
    cy.visit(`${baseUrl}/records/1`);
    cy.get('[data-testid="record-detail"]').should('be.visible');
  });

  it('should successfully add a comment to a record', () => {
    const commentText = 'This is a test comment on the record.';

    cy.get('[data-testid="comment-input"]').should('be.visible');
    cy.get('[data-testid="comment-input"]').click();
    cy.get('[data-testid="comment-input"]').type(commentText);
    cy.get('[data-testid="submit-comment-btn"]').click();

    cy.get('[data-testid="comment-list"]').should('contain', commentText);
    cy.get('[data-testid="comment-item"]').first().should('contain', testUser.email);
    cy.get('[data-testid="comment-timestamp"]').first().should('be.visible');
  });

  it('should not submit an empty comment', () => {
    cy.get('[data-testid="comment-input"]').should('be.visible');
    cy.get('[data-testid="comment-input"]').click();
    cy.get('[data-testid="submit-comment-btn"]').should('be.disabled');

    cy.get('[data-testid="comment-list"]').children().then(($comments) => {
      const initialCount = $comments.length;
      cy.get('[data-testid="submit-comment-btn"]').click({ force: true });
      cy.get('[data-testid="comment-list"]').children().should('have.length', initialCount);
    });
  });

  it('should display validation error for comment exceeding character limit', () => {
    const longComment = 'a'.repeat(5001);

    cy.get('[data-testid="comment-input"]').type(longComment);
    cy.get('[data-testid="char-count"]').should('contain', '5000');
    cy.get('[data-testid="submit-comment-btn"]').should('be.disabled');
    cy.get('[data-testid="error-message"]').should('contain', 'Comment must not exceed 5000 characters');
  });

  it('should edit an existing comment', () => {
    const originalComment = 'Original comment text';
    const editedComment = 'Updated comment text';

    cy.get('[data-testid="comment-input"]').type(originalComment);
    cy.get('[data-testid="submit-comment-btn"]').click();
    cy.get('[data-testid="comment-item"]').first().should('contain', originalComment);

    cy.get('[data-testid="comment-item"]').first().within(() => {
      cy.get('[data-testid="edit-comment-btn"]').click();
    });

    cy.get('[data-testid="comment-edit-input"]').clear().type(editedComment);
    cy.get('[data-testid="save-edit-btn"]').click();

    cy.get('[data-testid="comment-item"]').first().should('contain', editedComment);
    cy.get('[data-testid="comment-item"]').first().should('contain', 'edited');
  });

  it('should delete a comment with confirmation', () => {
    const commentText = 'Comment to be deleted';

    cy.get('[data-testid="comment-input"]').type(commentText);
    cy.get('[data-testid="submit-comment-btn"]').click();
    cy.get('[data-testid="comment-item"]').first().should('contain', commentText);

    cy.get('[data-testid="comment-item"]').first().within(() => {
      cy.get('[data-testid="delete-comment-btn"]').click();
    });

    cy.get('[data-testid="delete-confirmation-modal"]').should('be.visible');
    cy.get('[data-testid="confirm-delete-btn"]').click();

    cy.get('[data-testid="comment-list"]').should('not.contain', commentText);
  });

  it('should display comments in chronological order', () => {
    const comments = [
      'First comment',
      'Second comment',
      'Third comment'
    ];

    comments.forEach((comment) => {
      cy.get('[data-testid="comment-input"]').type(comment);
      cy.get('[data-testid="submit-comment-btn"]').click();
      cy.get('[data-testid="comment-input"]').should('have.value', '');
      cy.wait(500);
    });

    cy.get('[data-testid="comment-item"]').then(($items) => {
      expect($items.length).to.equal(3);
      expect($items.eq(0).text()).to.include(comments[0]);
      expect($items.eq(1).text()).to.include(comments[1]);
      expect($items.eq(2).text()).to.include(comments[2]);
    });
  });
});
